//go:build amd64

package minlz

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"testing"
)

// Golden outputs are generated by the independent pinned upstream, including
// incompressible fallback and all five levels at length-header boundaries.
func TestLengthHeaderGolden(t *testing.T) {
	fixture := "testdata/length-header-golden.json"
	if !hasAsm {
		fixture = "testdata/length-header-golden-purego.json"
	}
	data, err := os.ReadFile(fixture)
	if err != nil {
		t.Fatal(err)
	}
	var cases []struct {
		N, Kind, Level, Bytes int
		SHA                   string
	}
	if err := json.Unmarshal(data, &cases); err != nil {
		t.Fatal(err)
	}
	for _, c := range cases {
		src := lengthHeaderInput(c.N, c.Kind)
		original := bytes.Clone(src)
		for _, alignment := range []int{0, 1, 31} {
			capacity := MaxEncodedLen(len(src))
			storage := bytes.Repeat([]byte{0xb7}, 64+alignment+capacity+64)
			dst := storage[64+alignment : 64+alignment : 64+alignment+capacity]
			out, err := Encode(dst, src, c.Level)
			if err != nil {
				t.Fatal(err)
			}
			hash := sha256.Sum256(out)
			if len(out) != c.Bytes || hex.EncodeToString(hash[:]) != c.SHA {
				t.Fatalf("n=%d kind=%d level=%d alignment=%d: encoded bytes differ", c.N, c.Kind, c.Level, alignment)
			}
			decoded, err := Decode(nil, out)
			if err != nil || !bytes.Equal(decoded, src) {
				t.Fatal("roundtrip", err)
			}
			if !bytes.Equal(storage[:64+alignment], bytes.Repeat([]byte{0xb7}, 64+alignment)) || !bytes.Equal(storage[len(storage)-64:], bytes.Repeat([]byte{0xb7}, 64)) || !bytes.Equal(src, original) {
				t.Fatalf("n=%d kind=%d level=%d: source or destination guard changed", c.N, c.Kind, c.Level)
			}
			want := bytes.Clone(out)
			prefix := make([]byte, 3, 3+capacity)
			copy(prefix, []byte{9, 8, 7})
			appended, err := AppendEncoded(prefix, src, c.Level)
			if err != nil || !bytes.Equal(appended[:3], []byte{9, 8, 7}) || !bytes.Equal(appended[3:], want) {
				t.Fatal("append differs", err)
			}
			try := TryEncode(dst, src, c.Level)
			if len(want) < len(src) {
				if !bytes.Equal(try, want) {
					t.Fatal("TryEncode differs")
				}
			} else if try != nil {
				t.Fatal("TryEncode should decline")
			}
		}
	}
}

func lengthHeaderInput(n, kind int) []byte {
	src := make([]byte, n)
	x := uint64(0xa0761d6478bd642f) ^ uint64(n)
	for i := range src {
		x ^= x << 13
		x ^= x >> 7
		x ^= x << 17
		src[i] = byte(x)
	}
	if kind == 1 {
		for i := 73; i < n; i++ {
			src[i] = src[i%73]
		}
	}
	if kind == 2 {
		for i := 71; i+8 < n; i += 127 {
			copy(src[i:i+8], src[i-63:i-55])
		}
	}
	return src
}
